        System.out.println(evaluator.evaluate(1, 95)); // breach, enters pending (streak 1)
        System.out.println(evaluator.evaluate(2, 92)); // still breaching, pending (streak 2)
        System.out.println(evaluator.evaluate(3, 60)); // recovers before required duration, blip suppressed, back to ok

        System.out.println(evaluator.evaluate(4, 95)); // breach again, pending (streak 1)
        System.out.println(evaluator.evaluate(5, 93)); // pending (streak 2)
        System.out.println(evaluator.evaluate(6, 91)); // sustained for 3 straight breaches, now firing

        System.out.println(evaluator.evaluate(7, 80)); // below fire threshold but above resolve threshold, stays firing
        System.out.println(evaluator.evaluate(8, 65)); // below the lower resolve threshold, genuinely resolves
    }
}

