// number of consecutive samples before actually firing, filtering out brief
// blips, and a firing alert only resolves once the metric drops below a
// separate, lower resolve threshold, preventing rapid flapping at the boundary.
class AlertEvaluator {
    enum State { OK, PENDING, FIRING }

    private final double fireThreshold;
    private final double resolveThreshold;
    private final int requiredBreachTicks;

    private State state = State.OK;
    private int breachStreak = 0;

    AlertEvaluator(double fireThreshold, double resolveThreshold, int requiredBreachTicks) {
        this.fireThreshold = fireThreshold;
        this.resolveThreshold = resolveThreshold;
        this.requiredBreachTicks = requiredBreachTicks;
    }

    String evaluate(long timestamp, double value) {
        boolean isBreaching = value >= fireThreshold;

        if (state == State.FIRING) {
            if (value <= resolveThreshold) {
                state = State.OK;
                breachStreak = 0;
            }
        } else { // OK or PENDING
            if (isBreaching) {
                breachStreak++;
                state = (breachStreak >= requiredBreachTicks) ? State.FIRING : State.PENDING;
            } else {
                breachStreak = 0;
                state = State.OK;
            }
        }

        return "t=" + timestamp + ": value=" + value + " -> " + state;
    }
}

