#include <iostream>
#include <string>
using namespace std;

// A monitoring alert evaluator: a breach must be sustained for a required
// number of consecutive samples before actually firing, filtering out brief
// blips, and a firing alert only resolves once the metric drops below a
// separate, lower resolve threshold, preventing rapid flapping at the boundary.
class AlertEvaluator {
public:
    AlertEvaluator(double fireThreshold, double resolveThreshold, int requiredBreachTicks)
        : fireThreshold(fireThreshold), resolveThreshold(resolveThreshold),
          requiredBreachTicks(requiredBreachTicks), state("OK"), breachStreak(0) {}

    string evaluate(long long timestamp, double value) {
        bool isBreaching = value >= fireThreshold;

        if (state == "FIRING") {
            if (value <= resolveThreshold) {
                state = "OK";
                breachStreak = 0;
            }
        } else { // OK or PENDING
            if (isBreaching) {
                breachStreak++;
                state = (breachStreak >= requiredBreachTicks) ? "FIRING" : "PENDING";
            } else {
                breachStreak = 0;
                state = "OK";
            }
        }

        return "t=" + to_string(timestamp) + ": value=" + to_string(value) + " -> " + state;
    }

private:
    double fireThreshold;
    double resolveThreshold;
    int requiredBreachTicks;
    string state;
    int breachStreak;
};

int main() {
    AlertEvaluator evaluator(90.0, 70.0, 3); // fire at 90, resolve at 70, needs 3 sustained breaches

    cout << evaluator.evaluate(1, 95) << endl; // breach, enters pending (streak 1)
    cout << evaluator.evaluate(2, 92) << endl; // still breaching, pending (streak 2)
    cout << evaluator.evaluate(3, 60) << endl; // recovers before required duration, blip suppressed, back to ok

    cout << evaluator.evaluate(4, 95) << endl; // breach again, pending (streak 1)
    cout << evaluator.evaluate(5, 93) << endl; // pending (streak 2)
    cout << evaluator.evaluate(6, 91) << endl; // sustained for 3 straight breaches, now firing

    cout << evaluator.evaluate(7, 80) << endl; // below fire threshold but above resolve threshold, stays firing
    cout << evaluator.evaluate(8, 65) << endl; // below the lower resolve threshold, genuinely resolves

    return 0;
}

